-- 602: Original BrillaPrep Cambridge IGCSE Chemistry (0620) sprint 3 beta questions, part 9 of 13 (batch igcse-chemistry-sprint3-001).
-- Curriculum-aligned practice content; not official Cambridge International, WAEC or NSMQ examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_602_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_602_guard;
INSERT INTO _migration_602_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_033' AND NOT (q.topic_id IS 'topic_igcse_chem_organic' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which monomer is used to manufacture poly(ethene)?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Ethane","B. Ethyne","C. Chloroethene","D. Ethene"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Poly(ethene) forms by the addition polymerisation of ethene monomers, whose C=C double bonds open up and link together. (Ethane is saturated and cannot polymerise by addition; chloroethene gives poly(chloroethene), PVC.) Therefore the correct answer is D: Ethene.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_033' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_602_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_034' AND NOT (q.topic_id IS 'topic_igcse_chem_organic' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Ethanol reacts with ethanoic acid in the presence of a few drops of concentrated sulfuric acid as a catalyst. What are the products of this esterification reaction?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Ethyl ethanoate and water","B. Ethyl methanoate and water","C. Ethene and water","D. Ethyl ethanoate and hydrogen"]' AND q.correct_answer IS 'A' AND q.explanation IS 'An alcohol and a carboxylic acid react to form an ester and water: C₂H₅OH + CH₃COOH → CH₃COOC₂H₅ + H₂O. The ester from ethanol and ethanoic acid is ethyl ethanoate. (Ethyl methanoate would need methanoic acid; ethene and water come from dehydrating ethanol; hydrogen is not a product of condensation.) Therefore the correct answer is A: Ethyl ethanoate and water.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Deduce' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_034' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_602_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_035' AND NOT (q.topic_id IS 'topic_igcse_chem_organic' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'During cracking, one molecule of decane, C₁₀H₂₂, produces one molecule of octane, C₈H₁₈, and one molecule of X. What is X?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Ethane, C₂H₆","B. Ethene, C₂H₄","C. Methane, CH₄","D. Propene, C₃H₆"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The atoms must balance: C₁₀H₂₂ − C₈H₁₈ leaves C₂H₄, which is ethene. Cracking always produces at least one alkene. (C₂H₆ would make the hydrogen count 24, not 22; CH₄ would leave only 9 carbons accounted for; C₃H₆ would need 11 carbons in total.) Therefore the correct answer is B: Ethene, C₂H₄.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Deduce' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_035' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_602_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_036' AND NOT (q.topic_id IS 'topic_igcse_chem_electrolysis' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Molten lead(II) bromide is electrolysed using inert electrodes. What is formed at the cathode?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Bromine","B. Oxygen","C. Lead","D. Hydrogen"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The cathode is the negative electrode, attracting the positive Pb²⁺ ions, which gain electrons and are discharged as molten lead: Pb²⁺ + 2e⁻ → Pb. (Bromine forms at the anode; there is no oxygen or hydrogen in the melt.) Therefore the correct answer is C: Lead.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_036' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_033', 'topic_igcse_chem_organic', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'Which monomer is used to manufacture poly(ethene)?', 'multiple_choice', NULL, '["A. Ethane","B. Ethyne","C. Chloroethene","D. Ethene"]', 'D', 'Poly(ethene) forms by the addition polymerisation of ethene monomers, whose C=C double bonds open up and link together. (Ethane is saturated and cannot polymerise by addition; chloroethene gives poly(chloroethene), PVC.) Therefore the correct answer is D: Ethene.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, 'board_cambridge');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_034', 'topic_igcse_chem_organic', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'Ethanol reacts with ethanoic acid in the presence of a few drops of concentrated sulfuric acid as a catalyst. What are the products of this esterification reaction?', 'multiple_choice', NULL, '["A. Ethyl ethanoate and water","B. Ethyl methanoate and water","C. Ethene and water","D. Ethyl ethanoate and hydrogen"]', 'A', 'An alcohol and a carboxylic acid react to form an ester and water: C₂H₅OH + CH₃COOH → CH₃COOC₂H₅ + H₂O. The ester from ethanol and ethanoic acid is ethyl ethanoate. (Ethyl methanoate would need methanoic acid; ethene and water come from dehydrating ethanol; hydrogen is not a product of condensation.) Therefore the correct answer is A: Ethyl ethanoate and water.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Deduce', 'AO3', NULL, NULL, 'board_cambridge');
